// Normalize URL (ensure https) and basic domain extraction
const raw = $json.url_raw || '';
let url = raw.trim();
if (!/^https?:\/\//i.test(url) && url) {
  url = 'https://' + url;
}
const u = (()=>{ try { return new URL(url); } catch(e){ return null; } })();
const domain = u ? u.hostname.replace(/^www\./,'') : '';
return [{ url, domain }];

// Extract basic homepage insights + sector detection
const out = { sector_detected: '', city: '', metrics: {}, meta: {}, images_without_alt: 0, raw: $json };
try {
  const item = $json.tasks?.[0]?.result?.[0];
  if (item) {
    const dp = item.items?.page_timing || {};
    const vitals = item.items?.metrics || {};
    out.metrics = {
      lcp: vitals?.largest_contentful_paint || null,
      fid: vitals?.first_input_delay || null,
      cls: vitals?.cumulative_layout_shift || null,
      load_time: dp?.load_time || null,
      page_size_kb: item.items?.content?.size || null
    };
    const meta = item.items?.meta || {};
    out.meta = { title: meta?.title || '', description: meta?.description || '', h1: (item.items?.h1?.[0]?.text) || '' };
    const html = item.items?.html || '';
    const noAlt = (html.match(/<img(?![^>]*alt=)/gi) || []).length;
    out.images_without_alt = noAlt;
    const textForSector = (out.meta.title + ' ' + out.meta.description + ' ' + out.meta.h1).toLowerCase();
    const sectors = ['paysagiste','jardinier','plombier','electricien','menuisier','peintre','maçon','couvreur'];
    out.sector_detected = sectors.find(s=> textForSector.includes(s)) || '';
    const cityMatch = (out.meta.title + ' ' + out.meta.description).match(/\b(Paris|Lyon|Marseille|Toulouse|Nice|Nantes|Strasbourg|Montpellier|Bordeaux|Lille)\b/i);
    out.city = cityMatch ? cityMatch[1] : '' ;
  }
} catch(e) { out.error = String(e); }
return [out];

// Build SERP keyword from sector + city
const sectorInput = $('Set_Inputs').item.json.secteur_input || '';
const home = $json;
const sector = sectorInput || home.sector_detected || 'paysagiste';
const city = home.city || 'Paris';
const kw = `${sector} ${city}`.trim();
return [{ keyword: kw, city }];

// Summarize crawl pages inventory and flags
const res = $json.tasks?.[0]?.result?.[0];
const pages = res?.items || [];
const summary = { total_pages: pages.length, types: { services:0, blog:0, contact:0, a_propos:0 }, problems: [], meta_coverage: { title:0, description:0 }, content_lengths: [], internal_links:0, status_ok:0, status_errors:0 };
for (const p of pages) {
  const url = p.url || '';
  const status = p.status_code || p.http_status || 0;
  if (status >=200 && status<300) summary.status_ok++; else summary.status_errors++;
  const title = p.title || p.meta?.title || '';
  const h1 = p.h1?.[0]?.text || p.h1 || '';
  const desc = p.meta?.description || '';
  if (title) summary.meta_coverage.title++;
  if (desc) summary.meta_coverage.description++;
  const textLen = (p.content?.plain_text || '').length || (p.content?.length || 0);
  summary.content_lengths.push(textLen);
  const links = p.links_internal_count || 0;
  summary.internal_links += links;
  const u = url.toLowerCase();
  if (/service|prestation|amenagement|jardin/.test(u)) summary.types.services++;
  if (/blog|article|actus|actualite/.test(u)) summary.types.blog++;
  if (/contact/.test(u)) summary.types.contact++;
  if (/about|a-propos|a_propos/.test(u)) summary.types.a_propos++;
  if (status === 404) summary.problems.push(`404: ${url}`);
  if (status >= 300 && status < 400) summary.problems.push(`Redirect: ${url}`);
}
const below300 = summary.content_lengths.filter(n=> n < 300).length;
summary.problems = summary.problems.concat(below300? [`${below300} pages < 300 mots`] : []);
return [summary];

// Extract ranked keywords list with filters
const items = $json.tasks?.[0]?.result?.[0]?.items || [];
const filtered = items.filter(k=> (k.rank_absolute||k.rank)||999 <= 50)
  .map(k=> ({ term: k.keyword || k.keyword_data?.keyword, position: k.rank_absolute || k.rank, volume: k.search_volume || k.keyword_data?.search_volume || 0, difficulty: k.keyword_data?.keyword_difficulty || k.keyword_difficulty || null }))
  .sort((a,b)=> (b.volume||0) - (a.volume||0))
  .slice(0,50);
return [{ keywords: filtered }];

// Extract industry recurring terms from SERP titles/descriptions
const results = $json.tasks?.[0]?.result?.[0]?.items || [];
const urls = results.slice(0,10).map(r=> r.url);
const text = results.map(r=> (r.title||'') + ' ' + (r.description||'')).join(' ').toLowerCase();
const tokens = text.match(/[a-zàâçéèêëîïôûùüÿñæœ-]{4,}/gi) || [];
const freq = {};
tokens.forEach(t=> freq[t]=(freq[t]||0)+1);
const common = Object.entries(freq).filter(([w,c])=> c>1).sort((a,b)=> b[1]-a[1]).slice(0,30).map(([w,c])=> w);
return [{ top_urls: urls, recurring_terms: common }];

// Compute scores as per spec
const home = $('Extract_Homepage_Insight').item.json;
const crawl = $('Summarize_Crawl').item.json;
const rk = $('Extract_Ranked_Keywords').item.json.keywords || [];
// Performance Mobile
const load = home.metrics.load_time || 0;
let loadScore = 0;
if (load <= 2000) loadScore = 100; else if (load >= 5000) loadScore = 0; else loadScore = Math.round(100 * (5000 - load) / 3000);
const size = home.metrics.page_size_kb || 0;
let sizeScore = 0;
if (size <= 1024) sizeScore = 100; else if (size >= 3072) sizeScore = 0; else sizeScore = Math.round(100 * (3072 - size) / 2048);
const vitals = home.metrics;
let vitalsScore = 0;
const lcp = vitals.lcp || 0; const cls = vitals.cls || 0;
let lcpScore = lcp? (lcp<=2500? 100 : lcp>=4000? 0 : Math.round(100*(4000-lcp)/1500)) : 50;
let clsScore = cls? (cls<=0.1? 100 : cls>=0.25? 0 : Math.round(100*(0.25-cls)/0.15)) : 50;
vitalsScore = Math.round((lcpScore + clsScore)/2);
const perfMobile = Math.round(0.4*loadScore + 0.3*sizeScore + 0.3*vitalsScore);
// Santé Technique
const total = crawl.total_pages || 0;
const okRate = total? Math.round(100 * (crawl.status_ok||0)/total) : 0;
const metaCov = total? Math.round(100 * (Math.min(crawl.meta_coverage.title, crawl.meta_coverage.description))/ total) : 0;
const mobileProblems = (home.images_without_alt>0? 10:0);
const tech = Math.round(0.4*okRate + 0.3*metaCov + 0.3*(100 - mobileProblems));
// SEO Global
const top20 = rk.filter(k=> (k.position||99) <= 20).length;
const metaQuality = metaCov;
const contentStructure = total? Math.round(100 * (1 - (crawl.content_lengths.filter(n=> n<300).length / total))) : 0;
const internalLinks = total? Math.min(100, Math.round( (crawl.internal_links / (total*5)) * 100)) : 0;
const noErrors = 100 - Math.min(100, Math.round(100 * (crawl.status_errors||0) / (total||1)));
let seo = Math.round(0.3*(Math.min(100, top20*10)) + 0.25*metaQuality + 0.2*contentStructure + 0.15*internalLinks + 0.1*noErrors);
if ((rk.length||0)===0) seo = 0;
return [{ perfMobile, tech, seo }];

// Build AI prompt per spec in French
const inputs = $('Set_Inputs').item.json;
const home = $('Extract_Homepage_Insight').item.json;
const crawl = $('Summarize_Crawl').item.json;
const rk = $('Extract_Ranked_Keywords').item.json.keywords || [];
const serp = $('Analyze_SERP').item.json;
const scores = $('Compute_Scores').item.json;
const prompt = `Contexte : Tu analyses le site ${inputs.client_name||''} (${ $('Normalize_URL').item.json.url }) dans le secteur ${inputs.secteur_input || home.sector_detected || 'paysagiste'}.

Données fournies :
- Performance mobile : ${JSON.stringify(home.metrics)}
- Inventaire contenu : ${crawl.total_pages||0} pages, types: ${JSON.stringify(crawl.types)}
- Mots-clés actuels : ${rk.map(k=> k.term+':'+k.position).join(', ').slice(0,1800)}
- Opportunités SEO (industrie, SERP): termes récurrents ${ (serp.recurring_terms||[]).slice(0,20).join(', ') }
- Problèmes techniques : ${ (crawl.problems||[]).slice(0,10).join('; ') }

Tâche 1 : Génère UN VERDICT en 1 phrase
Tâche 2 : Génère 10 ACTIONS PRIORITAIRES (Description max 15 mots, Impact: Élevé/Moyen/Faible, Effort: Rapide/Moyen/Long, Justification concise)
Tâche 3 : Identifie les LACUNES DE CONTENU (TOFU/MOFU/BOFU)
Tâche 4 : Liste 5 OPPORTUNITÉS MOTS-CLÉS (Terme, Volume, Difficulté, Raison)
Contraintes : Langage clair, pas de jargon, chiffres précis uniquement, pas de recommandations vagues. Réponds en JSON strict selon le schéma fourni.`;
return [{ prompt }];

// Assemble final JSON result
const inputs = $('Set_Inputs').item.json;
const url = $('Normalize_URL').item.json.url;
const home = $('Extract_Homepage_Insight').item.json;
const crawl = $('Summarize_Crawl').item.json;
const rk = $('Extract_Ranked_Keywords').item.json.keywords || [];
const serp = $('Analyze_SERP').item.json;
const scores = $('Compute_Scores').item.json;
const ai = $json;
const startedAt = new Date(inputs.started_at);
const endedAt = new Date();
const durationMs = endedAt - startedAt;
const mins = Math.floor(durationMs/60000);
const secs = Math.round((durationMs%60000)/1000);
function uuidv4(){return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,function(c){const r=Math.random()*16|0,v=c=='x'?r:(r&0x3|0x8);return v.toString(16);});}
const res = {
  meta: { audit_id: uuidv4(), date_audit: new Date().toISOString(), duree_execution: `${mins}m ${secs}s` },
  client: { nom: inputs.client_name||'', url, secteur: inputs.secteur_input || home.sector_detected || 'détecté automatiquement' },
  resume_express: { score_global: scores.seo, score_mobile: scores.perfMobile, score_technique: scores.tech, verdict: ai.verdict || '' },
  top_10_actions: (ai.top_10_actions||[]).map((a,i)=> ({ numero: i+1, action: a.action, impact: a.impact, effort: a.effort, justification: a.justification||'' })),
  analyse_seo: {
    mots_cles_actuels: rk.map(k=> ({ terme: k.term, position: k.position, volume: k.volume })),
    opportunites: (ai.opportunites_mots_cles||[]).map(o=> ({ terme: o.terme, volume_mensuel: o.volume_mensuel, difficulte: o.difficulte, raison: o.raison||'' })),
    contenu_manquant: { tofu: ai.contenu_manquant?.tofu||[], mofu: ai.contenu_manquant?.mofu||[], bofu: ai.contenu_manquant?.bofu||[] }
  },
  inventaire_site: { total_pages: crawl.total_pages||0, types_detectes: crawl.types||{}, problemes: crawl.problems||[] },
  donnees_brutes: { insight_homepage: null, crawl_complet: null, donnees_partielles: false }
};
if (!home.metrics || Object.keys(home.metrics).length===0) { res.resume_express.score_technique = 'N/A'; }
if ((rk||[]).length===0) { res.resume_express.score_global = 0; }
if (!crawl.total_pages) { res.donnees_brutes.donnees_partielles = true; }
return [res];
